<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { api } from '../../lib/api'
import { ABILITY_KEYS } from '../../lib/calc'
import { MONSTER_BENEFIT_TYPES } from '../../../shared/monster-benefits'
import { BENEFIT_TYPES, benefitField, benefitKey, benefitObject, benefitSummary, benefitTitle, newRuleBenefit } from '../../../shared/rule-benefits'
const props=defineProps<{modelValue:unknown[];kind?:string;label?:string;spellChoices?:{index:string;name:string}[]}>()
const emit=defineEmits<{'update:modelValue':[unknown[]]}>()
const spells=ref<{index:string;name:string}[]>([]),spellError=ref('')
const ordered=computed(()=>Object.entries(BENEFIT_TYPES).filter(([key])=>props.kind!=='monsters'||MONSTER_BENEFIT_TYPES.includes(key)).sort((a,b)=>a[1].label.localeCompare(b[1].label)))
const help=computed(()=>props.kind==='spells'?'These benefits apply while this spell’s effect is switched on in Combat. Knowing or preparing the spell does not activate it.':props.kind==='equipment'||props.kind==='magic-items'?'These benefits apply while the item is equipped and, when required, attuned.':props.kind==='monsters'?'These benefits update this creature’s statistics. They do not grant benefits to a character viewing the entry.':'These benefits apply after the character’s review, at the unlock level. Class and subclass benefits use that class’s level; other benefits use character level.')
function spec(row:unknown){const key=benefitKey(benefitField(row,'type'));return Object.hasOwn(BENEFIT_TYPES,key)?BENEFIT_TYPES[key]:undefined}
function set(index:number,key:string,value:unknown){const old=benefitObject(props.modelValue[index]),field=Object.hasOwn(old,`:${key}`)?`:${key}`:key;emit('update:modelValue',props.modelValue.map((r,i)=>i===index?{...old,[field]:value}:r))}
function type(index:number,value:string){const old=benefitObject(props.modelValue[index]),next={...old},colon=Object.hasOwn(old,':type');delete next.type;delete next[':type'];delete next.value;delete next[':value'];const fresh=newRuleBenefit(value);next[colon?':type':'type']=colon?':'+value:value;if(fresh.value!==undefined)next[colon?':value':'value']=colon&&typeof fresh.value==='string'?':'+fresh.value:fresh.value;emit('update:modelValue',props.modelValue.map((r,i)=>i===index?next:r))}
function value(index:number,next:string|number){const old=benefitField(props.modelValue[index],'value');set(index,'value',typeof next==='string'&&typeof old==='string'&&old.startsWith(':')?':'+next:next)}
function spellValue(index:number,key:string,value:unknown){const old=benefitObject(benefitField(props.modelValue[index],'value'));set(index,'value',{...old,[Object.hasOwn(old,`:${key}`)?`:${key}`:key]:value})}
async function loadSpells(){if(props.spellChoices){spells.value=props.spellChoices;return}spellError.value='';try{const [srd,homebrew]=await Promise.all([api.get<{results:{index:string;name:string}[]}>('/api/2014/spells'),api.get<{index:string;name:string;displayName?:string}[]>('/api/content/homebrew/spells')]);spells.value=[...(srd.results??[]),...homebrew.map(s=>({...s,name:s.displayName??s.name}))].sort((a,b)=>a.name.localeCompare(b.name))}catch{spellError.value='Spell choices could not load. Existing selections are kept.'}}
let spellChoicesStarted=false
watch(()=>props.modelValue.some(row=>spec(row)?.spell),needed=>{if(needed&&!spellChoicesStarted){spellChoicesStarted=true;void loadSpells()}},{immediate:true})
</script>
<template>
 <section class="entry-benefits" aria-label="Rule benefits"><h3 class="font-display">{{label??'Benefits by level'}}</h3><p class="entry-hint">{{help}}</p>
  <details v-for="(row,i) in modelValue" :key="i" class="entry-field-group" open><summary>{{benefitSummary(row)}} <small v-if="kind!=='monsters'">Level {{benefitField(row,'level')??1}}</small></summary><div class="entry-benefit-body">
   <div class="entry-benefit-controls"><label class="entry-field">Benefit type<select aria-label="Benefit type" class="input-base" :value="benefitKey(benefitField(row,'type'))" @change="type(i,($event.target as HTMLSelectElement).value)"><option v-if="!spec(row)" :value="benefitKey(benefitField(row,'type'))">{{benefitTitle(benefitField(row,'type'))}} · imported rule</option><option v-for="[key,s] in ordered" :key="key" :value="key">{{s.label}}</option></select></label>
   <label v-if="kind!=='monsters'" class="entry-field">Unlock at level<select aria-label="Unlock at level" class="input-base" :value="benefitField(row,'level')??1" @change="set(i,'level',Number(($event.target as HTMLSelectElement).value))"><option v-for="n in 20" :key="n" :value="n">{{n}}</option></select></label>
   <label v-if="spec(row)?.values" class="entry-field">{{spec(row)!.label}}<select :aria-label="spec(row)!.label" class="input-base" :value="benefitKey(benefitField(row,'value'))" @change="value(i,($event.target as HTMLSelectElement).value)"><option v-if="!spec(row)!.values!.includes(benefitKey(benefitField(row,'value')))" :value="benefitKey(benefitField(row,'value'))">{{benefitTitle(benefitField(row,'value'))}} · imported value</option><option v-for="option in spec(row)!.values" :key="option" :value="option">{{benefitTitle(option)}}</option></select></label>
   <label v-else-if="spec(row)?.min!==undefined" class="entry-field">{{spec(row)!.label}}{{spec(row)!.unit?' · '+spec(row)!.unit:''}}<input :aria-label="spec(row)!.label+(spec(row)!.unit?' · '+spec(row)!.unit:'')" class="input-base" type="number" step="1" :min="spec(row)!.min" :max="spec(row)!.max" :value="benefitField(row,'value')" required @input="value(i,($event.target as HTMLInputElement).valueAsNumber)" /></label></div>
   <div v-if="spec(row)?.spell" class="entry-benefit-controls"><label class="entry-field">Spell<select aria-label="Spell" class="input-base" :value="benefitKey(benefitField(benefitField(row,'value'),'key'))" required @change="spellValue(i,'key',($event.target as HTMLSelectElement).value)"><option value="" disabled>Choose a spell</option><option v-if="benefitField(benefitField(row,'value'),'key')&&!spells.some(s=>s.index===benefitKey(benefitField(benefitField(row,'value'),'key')))" :value="benefitKey(benefitField(benefitField(row,'value'),'key'))">{{benefitTitle(benefitField(benefitField(row,'value'),'key'))}} · saved reference</option><option v-for="spell in spells" :key="spell.index" :value="spell.index">{{spell.name}}</option></select></label><label class="entry-field">Spellcasting ability<select aria-label="Spellcasting ability" class="input-base" :value="benefitKey(benefitField(benefitField(row,'value'),'ability'))" @change="spellValue(i,'ability',($event.target as HTMLSelectElement).value)"><option v-for="a in ABILITY_KEYS" :key="a" :value="a">{{benefitTitle(a)}}</option></select></label><label class="entry-field">Spell level<select aria-label="Spell level" class="input-base" :value="benefitField(benefitField(row,'value'),'level')??0" @change="spellValue(i,'level',Number(($event.target as HTMLSelectElement).value))"><option v-for="n in 10" :key="n" :value="n-1">{{n===1?'Cantrip':n-1}}</option></select></label><p v-if="spellError" role="alert">{{spellError}} <button type="button" class="btn-ghost" @click="loadSpells">Retry spell choices</button></p></div>
   <p class="entry-hint">{{spec(row)?.hint??'This imported rule is preserved. Its effect is not automated; choose a supported type to replace it.'}}</p><button type="button" class="btn-ghost" :aria-label="`Remove benefit ${i+1}`" @click="emit('update:modelValue',modelValue.filter((_,n)=>n!==i))">Remove benefit</button>
  </div></details>
  <p v-if="!modelValue.length" class="entry-hint">No additional benefits. Add one to define an effect.</p><button type="button" class="btn-ghost" @click="emit('update:modelValue',[...modelValue,newRuleBenefit()])">Add benefit</button>
 </section>
</template>
